/**
 * Parla's settings page.
 *
 * Kept as a real file rather than printed into the page: WordPress.org expects admin assets to be
 * enqueued, and a file can be cached, versioned and read on its own. Everything the server knows is
 * handed over in the PARLA object (see parla_admin_assets), so nothing here is generated by PHP.
 */
/* global PARLA */
(function () {
    var root = document.querySelector('.aa-admin');
    if (!root) { return; }
    var tabs = root.querySelectorAll('.aa-tab');
    var subtabs = root.querySelectorAll('.aa-subtab');
    var subnav = document.getElementById('aa-subnav');
    var panels = root.querySelectorAll('.aa-panel');
    var preview = document.getElementById('aa-preview');
    var savebar = document.getElementById('aa-savebar');
    var form = document.getElementById('aa-form');
    // The settings pages, in the side menu's order, and the ones that change what the chat looks like.
    var SETTINGS = ['look', 'assistant', 'first', 'voice', 'knowledge', 'connection'];
    var WITH_PREVIEW = ['look', 'assistant', 'first', 'voice'];
    // Links and bookmarks from before the settings were regrouped still land somewhere sensible.
    var OLD = { appearance: 'look', widget: 'look' };
    var lastSettings = 'look';
    try { lastSettings = sessionStorage.getItem('aa-settings') || 'look'; } catch (e) {}

    function show(slug) {
        slug = OLD[slug] || slug;
        // The Settings tab reopens whichever settings page was used last.
        if (slug === 'settings') { slug = SETTINGS.indexOf(lastSettings) !== -1 ? lastSettings : 'look'; }
        var inSettings = SETTINGS.indexOf(slug) !== -1;
        var top = inSettings ? 'settings' : slug;
        tabs.forEach(function (t) { t.setAttribute('aria-selected', String(t.dataset.tab === top)); t.tabIndex = t.dataset.tab === top ? 0 : -1; });
        subtabs.forEach(function (t) { if (t.dataset.tab === slug) { t.setAttribute('aria-current', 'page'); } else { t.removeAttribute('aria-current'); } });
        if (subnav) { subnav.hidden = !inSettings; }
        root.classList.toggle('in-settings', inSettings);
        panels.forEach(function (p) { p.hidden = p.id !== 'aa-tab-' + slug; });
        if (preview) { preview.hidden = WITH_PREVIEW.indexOf(slug) === -1; }
        root.classList.toggle('has-preview', !!preview && WITH_PREVIEW.indexOf(slug) !== -1);
        // Nothing to save on the two summary tabs; elsewhere the bar reveals itself once a field changes.
        if (savebar) { savebar.hidden = !inSettings; }
        if (inSettings) { lastSettings = slug; }
        try { sessionStorage.setItem('aa-tab', slug); if (inSettings) { sessionStorage.setItem('aa-settings', slug); } } catch (e) {}
        if (location.hash !== '#' + slug) { history.replaceState(null, '', '#' + slug); }
    }
    subtabs.forEach(function (t) { t.addEventListener('click', function () { show(t.dataset.tab); }); });
    tabs.forEach(function (t, i) {
        t.addEventListener('click', function () { show(t.dataset.tab); });
        t.addEventListener('keydown', function (e) {
            var next = e.key === 'ArrowRight' ? i + 1 : e.key === 'ArrowLeft' ? i - 1 : null;
            if (next === null) { return; }
            var target = tabs[(next + tabs.length) % tabs.length];
            target.focus(); show(target.dataset.tab);
        });
    });
    root.querySelectorAll('[data-aa-go]').forEach(function (b) { b.addEventListener('click', function () { show(b.dataset.aaGo); }); });
    var wanted = location.hash.replace('#', '');
    try { wanted = wanted || sessionStorage.getItem('aa-tab'); } catch (e) {}
    wanted = OLD[wanted] || wanted;
    var valid = [].some.call(panels, function (p) { return p.id === 'aa-tab-' + wanted; }) || wanted === 'settings';
    show(valid ? wanted : PARLA.firstTab);

    // Sections that only apply to one choice (premium or standard voice).
    function syncConditional() {
        root.querySelectorAll('[data-aa-show-when]').forEach(function (el) {
            var parts = el.dataset.aaShowWhen.split('=');
            var on = form.querySelector('input[name="' + parts[0] + '"]:checked');
            el.hidden = !on || on.value !== parts[1];
        });
    }
    syncConditional();

    // Colour swatches show their hex; the speed slider shows its value.
    root.querySelectorAll('[data-aa-hex]').forEach(function (i) {
        i.addEventListener('input', function () { var c = document.getElementById(i.dataset.aaHex); if (c) { c.textContent = i.value; } });
    });
    // Openers: add up to six, remove any, never leave zero fields on the page.
    (function () {
        var box = document.getElementById('aa-openers');
        var add = document.getElementById('aa-opener-add');
        if (!box || !add) { return; }
        var max = parseInt(add.dataset.max, 10) || 6;
        function sync() {
            var rows = box.querySelectorAll('.aa-opener');
            add.hidden = rows.length >= max;
            rows.forEach(function (r) { r.querySelector('.aa-opener-x').hidden = rows.length <= 1; });
        }
        box.addEventListener('click', function (e) {
            var x = e.target.closest('.aa-opener-x');
            if (!x) { return; }
            if (box.querySelectorAll('.aa-opener').length > 1) { x.closest('.aa-opener').remove(); }
            sync();
            box.dispatchEvent(new Event('input', { bubbles: true }));
        });
        add.addEventListener('click', function () {
            var row = document.createElement('div');
            row.className = 'aa-opener';
            var input = document.createElement('input');
            input.name = 'opener_chips[]';
            input.type = 'text';
            input.maxLength = 80;
            input.className = 'aa-in';
            input.placeholder = add.dataset.placeholder;
            var x = document.createElement('button');
            x.type = 'button';
            x.className = 'aa-opener-x';
            x.setAttribute('aria-label', add.dataset.remove);
            x.innerHTML = '&times;';
            row.appendChild(input);
            row.appendChild(x);
            box.appendChild(row);
            input.focus();
            sync();
        });
        sync();
    })();

    // Ranked lists show their busiest eight and open the rest on a click.
    root.querySelectorAll('[data-aa-more]').forEach(function (b) {
        // The hidden rows are found by their own class anywhere in the card, so this works for a
        // ranked list and for the unhelpful-answers table without knowing which one it is.
        var card = b.closest('.aa-card') || b.parentElement;
        var hidden = card.querySelectorAll('.aa-more');
        if (!hidden.length) { return; }
        var open = false;
        var more = b.textContent;
        b.addEventListener('click', function () {
            open = !open;
            hidden.forEach(function (el) { el.hidden = !open; });
            b.textContent = open ? b.dataset.less : more;
            card.classList.toggle('is-expanded', open);
        });
    });

    // A waiting list shows five addresses; "Show all" opens the rest in a scrolling box with a search.
    root.querySelectorAll('[data-aa-addr-all]').forEach(function (b) {
        var body = b.closest('.aa-wg-body');
        var rest = body.querySelectorAll('.aa-addr-more');
        var find = body.querySelector('.aa-wg-find');
        var input = body.querySelector('[data-aa-addr-find]');
        var all = false;
        var more = b.textContent;
        b.addEventListener('click', function () {
            all = !all;
            rest.forEach(function (li) { li.hidden = !all; });
            body.classList.toggle('is-full', all);
            if (find) { find.hidden = !all; }
            if (!all && input) { input.value = ''; body.querySelectorAll('.aa-waiting-people li').forEach(function (li, i) { li.hidden = i >= 5; }); }
            b.textContent = all ? b.dataset.less : more;
            if (all && input) { input.focus(); }
        });
    });
    root.querySelectorAll('[data-aa-addr-find]').forEach(function (input) {
        var items = input.closest('.aa-wg-body').querySelectorAll('.aa-waiting-people li');
        input.addEventListener('input', function () {
            var q = input.value.trim().toLowerCase();
            items.forEach(function (li) { li.hidden = q !== '' && li.textContent.toLowerCase().indexOf(q) === -1; });
        });
        // Enter in this box would submit the settings form.
        input.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); } });
    });

    // Charts: the bar under the pointer says its own figure, just above it.
    root.querySelectorAll('[data-aa-bars]').forEach(function (bars) {
        var tip = document.createElement('div');
        tip.className = 'aa-tip';
        tip.setAttribute('aria-hidden', 'true');
        tip.hidden = true;
        // Beside the list rather than in it: a list holds only its items.
        var box = bars.closest('.aa-chart') || bars.parentElement;
        box.appendChild(tip);
        bars.addEventListener('mouseover', function (e) {
            var li = e.target.closest('li[data-tip]');
            if (!li || !bars.contains(li)) { return; }
            var bar = (li.querySelector('.aa-bar') || li).getBoundingClientRect();
            var at = box.getBoundingClientRect();
            tip.textContent = li.dataset.tip;
            tip.style.left = (bar.left + bar.width / 2 - at.left) + 'px';
            tip.style.top = (bar.top - at.top) + 'px';
            tip.hidden = false;
        });
        bars.addEventListener('mouseleave', function () { tip.hidden = true; });
    });

    // The notes box says how much room is left, because 300 characters is less than it sounds.
    root.querySelectorAll('.aa-count').forEach(function (p) {
        var box = document.getElementById(p.dataset.for);
        if (!box) { return; }
        var template = p.textContent.replace(/\d+/, '%d');
        var update = function () { p.textContent = template.replace('%d', String(box.maxLength - box.value.length)); };
        box.addEventListener('input', update);
        update();
    });
    var rate = document.getElementById('aa_voice_rate');
    if (rate) { rate.addEventListener('input', function () { rate.nextElementSibling.textContent = rate.value + '×'; }); }

    // Copy and show buttons.
    root.querySelectorAll('[data-aa-copy]').forEach(function (b) {
        b.addEventListener('click', function () {
            var f = document.getElementById(b.dataset.aaCopy);
            if (!f || !navigator.clipboard) { return; }
            navigator.clipboard.writeText(f.value).then(function () { var old = b.textContent; b.textContent = b.dataset.done; setTimeout(function () { b.textContent = old; }, 1500); });
        });
    });
    root.querySelectorAll('[data-aa-reveal]').forEach(function (b) {
        b.addEventListener('click', function () { var f = document.getElementById(b.dataset.aaReveal); if (f) { f.type = f.type === 'password' ? 'text' : 'password'; } });
    });
    root.querySelectorAll('[data-aa-confirm]').forEach(function (b) {
        b.addEventListener('click', function (e) { if (!window.confirm(b.dataset.aaConfirm)) { e.preventDefault(); } });
    });

    // Say so when something changed and has not been saved yet.
    var state = document.getElementById('aa-save-state');
    form.addEventListener('input', function (e) {
        syncConditional();
        // Switching the preview between closed and open is not a setting.
        if (e.target && e.target.name === 'aa_preview_view') { return; }
        // Neither is searching a waiting list.
        if (e.target && e.target.hasAttribute && e.target.hasAttribute('data-aa-addr-find')) { return; }
        if (savebar) { savebar.classList.add('is-dirty'); }
        if (state) { state.textContent = state.dataset.dirty; }
    });
    form.addEventListener('change', syncConditional);

    // Colours: presets, and a readable text colour picked for the merchant until they choose one.
    var main = form.querySelector('input[name="brand_color"]');
    var text = form.querySelector('input[name="brand_contrast"]');
    var textByHand = false;
    function readable(hex) {
        var m = /^#?([0-9a-f]{6})$/i.exec(hex || '');
        if (!m) { return '#ffffff'; }
        var n = parseInt(m[1], 16);
        var lin = [n >> 16, (n >> 8) & 255, n & 255].map(function (c) { c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); });
        var lum = 0.2126 * lin[0] + 0.7152 * lin[1] + 0.0722 * lin[2];
        // Pick whichever of black or white contrasts more.
        return (lum + 0.05) / 0.05 > 1.05 / (lum + 0.05) ? '#111111' : '#ffffff';
    }
    function setColour(input, value) {
        input.value = value;
        var c = document.getElementById(input.dataset.aaHex); if (c) { c.textContent = value; }
        input.dispatchEvent(new Event('input', { bubbles: true }));
    }
    if (main && text) {
        text.addEventListener('input', function (e) { if (e.isTrusted) { textByHand = true; } });
        main.addEventListener('input', function () { if (!textByHand) { setColour(text, readable(main.value)); } });
        root.querySelectorAll('[data-aa-preset]').forEach(function (b) {
            b.addEventListener('click', function () { textByHand = false; setColour(main, b.dataset.aaPreset); syncPresets(); });
        });
        function syncPresets() {
            root.querySelectorAll('[data-aa-preset]').forEach(function (b) { b.setAttribute('aria-pressed', String(b.dataset.aaPreset.toLowerCase() === main.value.toLowerCase())); });
        }
        main.addEventListener('input', syncPresets);
        syncPresets();
    }

    // The live preview follows the form as it is typed.
    var frame = document.getElementById('aa-preview-frame');
    if (frame) {
        var dark = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
        function val(name) {
            var els = form.querySelectorAll('[name="' + name + '"]');
            if (!els.length) { return undefined; }
            var el = els[0];
            if (el.type === 'radio') { var on = form.querySelector('[name="' + name + '"]:checked'); return on ? on.value : undefined; }
            if (el.type === 'checkbox') { return el.checked; }
            return el.value;
        }
        function push() {
            var w = frame.contentWindow, d = frame.contentDocument;
            if (!w || !d || !d.body) { return; }
            var brand = val('brand_color') || '#111827';
            var chat = d.querySelector('parla-chat');
            if (chat) {
                chat.style.setProperty('--parla-brand', brand);
                chat.style.setProperty('--parla-brand-contrast', val('brand_contrast') || '#ffffff');
            }
            var theme = val('theme') || 'auto';
            d.body.classList.toggle('dark', theme === 'dark' || (theme === 'auto' && !!dark && dark.matches));
            var buy = d.getElementById('buy'); if (buy) { buy.style.background = brand; }
            var name = (val('store_name') || '').trim() || PARLA.storeName;
            var shop = d.getElementById('shop'); if (shop) { shop.textContent = name; }
            var calls = val('voice_calls');
            var detail = {
                store_name: name,
                opener_chips: [].map.call(document.querySelectorAll('input[name="opener_chips[]"]'), function (i) { return i.value.trim(); }).filter(Boolean),
                show_track_order: val('show_track_order') !== false,
                agent_name: (val('agent_name') || '').trim(),
                agent_status: (val('agent_status') || '').trim(),
                locale: val('locale'),
                theme: theme,
                suggest_products: val('suggest_products'),
                voice_calls: calls === undefined ? undefined : !!calls,
                greeting: { text: val('greeting_text') || '', pages: val('greeting_pages') || 'all', after_seconds: 1 },
                open: val('aa_preview_view') === 'open'
            };
            // Greeting by name: shown with the admin's own first name, or a sample one when their profile has none.
            detail.customer_name = val('greet_customers') === false ? '' : PARLA.sampleName;
            w.dispatchEvent(new w.CustomEvent('parla:preview', { detail: detail }));
        }
        // Whichever comes first, the page load or the widget saying it listens, sends the draft.
        function top() {
            var d = frame.contentDocument;
            if (d && d.scrollingElement) { d.scrollingElement.scrollTop = 0; }
            if (preview) { preview.scrollTop = 0; }
        }
        function hook() {
            var w = frame.contentWindow;
            if (w && !w.__aaHooked) { w.__aaHooked = true; w.addEventListener('parla:preview-ready', function () { push(); top(); }); }
            push();
            top();
        }
        frame.addEventListener('load', hook);
        if (frame.contentDocument && frame.contentDocument.readyState === 'complete') { hook(); }
        var timer;
        function soon() { clearTimeout(timer); timer = setTimeout(push, 120); }
        form.addEventListener('input', soon);
        form.addEventListener('change', soon);
        if (dark && dark.addEventListener) { dark.addEventListener('change', soon); }
        // Coming back to a tab with the preview: make sure it shows the latest draft.
        tabs.forEach(function (t) { t.addEventListener('click', soon); });
        subtabs.forEach(function (t) { t.addEventListener('click', soon); });
    }
})();

(function () {
    var box = document.getElementById('aa-voices');
    var field = document.getElementById('aa_voice_name');
    if (!box || !field) { return; }
    if (!window.speechSynthesis) { box.textContent = box.dataset.none; return; }
    var NOVELTY = PARLA.novelty;
    var sample = PARLA.voiceSample;

    function chip(name, label, voice) {
        var b = document.createElement('button');
        b.type = 'button';
        b.className = 'aa-chip' + (field.value === name ? ' is-on' : '');
        b.textContent = label;
        b.addEventListener('click', function () {
            if (voice) {
                speechSynthesis.cancel();
                var u = new SpeechSynthesisUtterance(sample);
                u.voice = voice;
                u.rate = parseFloat((document.getElementById('aa_voice_rate') || {}).value) || 1.05;
                speechSynthesis.speak(u);
            }
            field.value = name;
            box.querySelectorAll('.aa-chip').forEach(function (c) { c.classList.toggle('is-on', c === b); });
            field.dispatchEvent(new Event('input', { bubbles: true }));
        });
        return b;
    }

    function render() {
        var wanted = (navigator.language || 'en').slice(0, 2);
        var voices = speechSynthesis.getVoices()
            .filter(function (v) { return v.lang.slice(0, 2) === wanted; })
            .filter(function (v) { return !NOVELTY.some(function (n) { return v.name.toLowerCase().indexOf(n) === 0; }); })
            .sort(function (a, b) { return (a.localService === b.localService) ? 0 : (a.localService ? 1 : -1); });
        if (!voices.length) { return; }
        box.textContent = '';
        // Empty is a real choice, and the default one: whatever the shopper's device does best.
        box.appendChild(chip('', box.dataset.best, null));
        voices.slice(0, 12).forEach(function (v) { box.appendChild(chip(v.name, v.name, v)); });
        // A voice chosen on another machine is still the setting, so it stays selectable here.
        var saved = box.dataset.saved;
        if (saved && !voices.some(function (v) { return v.name === saved; })) {
            box.appendChild(chip(saved, saved, null));
        }
    }
    render();
    speechSynthesis.onvoiceschanged = render;
})();

(function () {
    var box = document.getElementById('aa-premium-voices');
    var field = document.getElementById('aa_premium_voice_id');
    if (!box || !field) { return; }
    var API = PARLA.api;
    var lang = PARLA.lang;
    // Language headings, in the merchant's own words. An unlisted code falls back to itself.
    var NAMES = PARLA.languages;
    var playing = null;

    box.textContent = box.dataset.loading;

    function choose(id) {
        field.value = id;
        box.querySelectorAll('input[type="radio"]').forEach(function (r) { r.checked = r.value === id; });
        field.dispatchEvent(new Event('input', { bubbles: true }));
    }

    function play(url, button) {
        if (playing) { playing.audio.pause(); playing.button.classList.remove('is-playing'); }
        if (playing && playing.url === url) { playing = null; return; }
        var audio = new Audio(url);
        playing = { audio: audio, button: button, url: url };
        button.classList.add('is-playing');
        audio.addEventListener('ended', function () { button.classList.remove('is-playing'); playing = null; });
        // A clip that will not play (offline, not rendered yet) must not leave the button stuck.
        audio.addEventListener('error', function () { button.classList.remove('is-playing'); playing = null; });
        audio.play().catch(function () { button.classList.remove('is-playing'); playing = null; });
    }

    function option(id, name, note, url) {
        var label = document.createElement('label');
        label.className = 'aa-voiceopt';
        var radio = document.createElement('input');
        radio.type = 'radio';
        radio.name = 'aa_premium_pick';
        radio.value = id;
        radio.checked = field.value === id;
        radio.addEventListener('change', function () { choose(id); });
        var text = document.createElement('span');
        text.className = 'aa-voiceopt-text';
        var strong = document.createElement('strong');
        strong.textContent = name;
        text.appendChild(strong);
        if (note) {
            var small = document.createElement('small');
            small.textContent = note;
            text.appendChild(small);
        }
        label.appendChild(radio);
        label.appendChild(text);
        if (url) {
            var b = document.createElement('button');
            b.type = 'button';
            b.className = 'aa-voiceplay';
            b.setAttribute('aria-label', PARLA.i18n.play);
            b.textContent = '▶';
            // Inside a <label>, a click would also tick the radio: playing is not choosing.
            b.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); play(url, b); });
            label.appendChild(b);
        }
        return label;
    }

    function render(list) {
        box.textContent = '';
        if (!list.length) { box.textContent = box.dataset.empty; return; }

        /*
         * One language at a time, chosen with a pill.
         *
         * Thirty-nine voices under eight headings was a page you scrolled rather than a choice you
         * made, and a shop needs one language. This filters instead of folding: every language is
         * visible in the pill row, so nothing is hidden, and only five rows are on screen at once.
         */
        var groups = {};
        list.forEach(function (v) { (groups[v.lang] = groups[v.lang] || []).push(v); });
        var codes = Object.keys(groups).sort(function (a, b) {
            return a === lang ? -1 : b === lang ? 1 : (NAMES[a] || a).localeCompare(NAMES[b] || b);
        });
        // Open on the language of the voice already chosen, else the site's, else the first offered.
        var chosen = list.filter(function (v) { return v.id === field.value; })[0];
        var shown = (chosen && chosen.lang) || (groups[lang] ? lang : codes[0]);

        var pills = document.createElement('div');
        pills.className = 'aa-langpills';
        pills.setAttribute('role', 'tablist');
        pills.setAttribute('aria-label', box.dataset.langs || '');
        box.appendChild(pills);

        var rows = document.createElement('div');
        rows.className = 'aa-voicerows';
        box.appendChild(rows);

        function draw() {
            pills.textContent = '';
            codes.forEach(function (code) {
                var b = document.createElement('button');
                b.type = 'button';
                b.className = 'aa-langpill' + (code === shown ? ' is-on' : '');
                b.setAttribute('role', 'tab');
                b.setAttribute('aria-selected', String(code === shown));
                b.textContent = NAMES[code] || code.toUpperCase();
                // A tick when the shop's chosen voice lives under this language, so switching away
                // from it does not feel like the choice was lost.
                if (chosen && chosen.lang === code) { b.classList.add('has-pick'); }
                b.addEventListener('click', function () { shown = code; draw(); });
                pills.appendChild(b);
            });
            rows.textContent = '';
            // Parla's own pick stays first: a merchant who tried the voices can still back out.
            rows.appendChild(option('', box.dataset.auto, '', ''));
            (groups[shown] || []).forEach(function (v) { rows.appendChild(option(v.id, v.name, v.note, v.sample_url)); });
        }
        draw();

        // Choosing a voice re-marks which pill holds the pick.
        box.addEventListener('change', function () {
            chosen = list.filter(function (v) { return v.id === field.value; })[0];
            pills.querySelectorAll('.aa-langpill').forEach(function (p, i) {
                p.classList.toggle('has-pick', !!chosen && chosen.lang === codes[i]);
            });
        });
    }

    // no-store: this page is opened to change a setting, so it always asks for today's list.
    // A cached answer here is how a merchant ends up staring at a voice that no longer exists.
    fetch(API + '/v1/voices', { credentials: 'omit', cache: 'no-store' })
        .then(function (r) { return r.ok ? r.json() : { voices: [] }; })
        .then(function (d) { render((d && d.voices) || []); })
        .catch(function () { box.textContent = box.dataset.empty; });
})();
